/// Name of the profile holding the setup from before the first look.
pub const BEFORE_PROFILE: &str = "Before looks";

/// Every config path a look may change (and its snapshot restores).
pub const SNAPSHOT_PATHS: &[&str] = &[
    "theme",
    "bar",
    // The rail an Expressive bar style set up: a look clears the style and
    // these with it (exactly what `bar_styles::clear` resets).
    "side_bars.enabled",
    "side_bars.chips",
    "side_bars.icon_shape",
    "side_bars.width",
    "side_bars.chip_size",
    "side_bars.chip_spacing",
    "side_bars.chip_fill",
    "side_bars.right.enabled",
    "typography",
    "style",
    "desktop",
    "visualizers",
    "looks",
    "dock.media_chip",
    "wallpaper.desktop_clock",
    "wallpaper.clock_style",
    "wallpaper.clock_x",
    "wallpaper.clock_y",
    "wallpaper.clock_scale",
    "wallpaper.show_date",
    "wallpaper.show_weather",
    "wallpaper.audio_ring",
    "plugins.enabled",
    "plugins.disabled",
];

/// A desktop widget a look added: its id and its fingerprint as the look
/// placed it ([`widget_print`]). One you changed since no longer matches,
/// and is yours.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct OwnedWidget {
    pub id: String,
    pub print: String,
}

/// A setting a look changed on top of its bar and palette: the value it
/// set and the one before (`None`: the key was unset). The next look puts
/// `was` back while the setting still holds `set`.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct SettingUndo {
    pub path: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub was: Option<Value>,
    pub set: Value,
}

/// `[looks]`: which look is applied (empty: your own setup).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct LooksState {
    /// A built-in look's id, or one of yours ([`crate::user_looks`]).
    pub active: String,
    /// The look's palette came from the wallpaper (not its own seed).
    pub wallpaper_colors: bool,
    /// Plugins the applied look(s) switched on that were off before: ids
    /// added to `plugins.enabled`, and ids taken out of `plugins.disabled`.
    /// The next look (or "Restore my look") switches them back off unless
    /// it needs them too; plugins you had on are never in here.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub plugins_enabled: Vec<String>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub plugins_undisabled: Vec<String>,
    /// Plugins the look switched off (a look without the dock): the next
    /// look switches them back on.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub plugins_disabled: Vec<String>,
    /// Picking a look keeps your component designs instead of applying the
    /// look's own (Studio → Themes → Components). Off: a look changes them.
    pub keep_components: bool,
    /// The desktop widgets the look added.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub widgets: Vec<OwnedWidget>,
    /// The look recorded its widgets (set by every look since they stopped
    /// replacing yours; an older config's look widgets are found by kind
    /// and place instead).
    #[serde(skip_serializing_if = "std::ops::Not::not")]
    pub widgets_tracked: bool,
    /// The settings it changed on top ([`SettingUndo`]).
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub settings: Vec<SettingUndo>,
    /// Fingerprint of everything the look owns right after it was applied
    /// ([`crate::user_looks::owned_print`]): a later difference is a
    /// customization.
    #[serde(skip_serializing_if = "String::is_empty")]
    pub print: String,
}

/// Options picked next to the gallery.
#[derive(Copy, Clone, Debug, Default, PartialEq)]
pub struct LookOptions {
    /// Take the palette from the current wallpaper (the look's variant)
    /// instead of the look's own seed. Ignored without a wallpaper.
    pub wallpaper_colors: bool,
}

/// The audio visualizer a look turns on.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum LookVisualizer {
    None,
    Wave,
    Framed,
    Mirrored,
}

/// A look's bar.
#[derive(Copy, Clone, Debug, PartialEq)]
pub enum LookBar {
    /// A plain bar: layout, edge, screen frame, opacity, zone capsules and
    /// (`Some`) a height; otherwise the bar's size stays yours.
    Plain { layout: BarLayout, position: BarPosition, screen_frame: bool, opacity: f32, capsules: bool, height: Option<f32> },
    /// A bar style preset: its whole look, height, rail and signature items.
    Style(BarStyle),
}

/// What a look does with the dock.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum LookDock {
    /// Left as you have it.
    Keep,
    /// Switched off while the look is on.
    Off,
    /// Switched on, centred at the bottom, magnifying or not.
    On { magnification: bool },
}

/// One look.
#[derive(Copy, Clone, Debug, PartialEq)]
pub struct LookDef {
    pub id: &'static str,
    pub name: &'static str,
    pub blurb: &'static str,
    /// OKLCH `(lightness, chroma, hue°)` seed for the HCT palette.
    pub seed: (f32, f32, f32),
    pub variant: SchemeVariant,
    pub dark: bool,
    pub bar: LookBar,
    /// Bar zones (start, middle, end; top → bottom on a side bar).
    pub zones: [&'static [&'static str]; 3],
    pub ui_font: &'static str,
    pub display_font: &'static str,
    pub radius_scale: f32,
    pub now_playing: Option<Anchor>,
    pub calendar: Option<Anchor>,
    pub visualizer: LookVisualizer,
    /// The desktop clock widget (`None`: no clock).
    pub clock: Option<(ClockFace, Anchor)>,
    /// The clock sits behind the wallpaper's subject (else in front).
    pub depth: bool,
    /// A system monitor column at this anchor.
    pub monitor: Option<Anchor>,
    /// A vertical text decoration (Arabic / katakana) on the end edge.
    pub decoration: Option<&'static str>,
    pub dock_media_chip: bool,
    /// The component designs the look brings (buttons, toggles, fields,
    /// chips, progress and cards), unless `looks.keep_components`.
    pub components: ComponentPreset,
    pub dock: LookDock,
    /// The motion feel (`None`: yours stays).
    pub motion: Option<MotionPreset>,
    /// A launcher look ([`crate::workflow::LAUNCHER_LOOKS`] id; `None`:
    /// yours stays).
    pub launcher: Option<&'static str>,
    /// Where notifications pop up (`None`: yours stays).
    pub toasts: Option<ToastPosition>,
    /// The bar hides until the pointer touches its edge (`None`: yours).
    pub auto_hide: Option<AutoHideMode>,
    /// Hot corners switched on with these actions (top-left, top-right,
    /// bottom-left, bottom-right; `None`: yours stay).
    pub corners: Option<[CornerAction; 4]>,
    /// Inked surfaces ([`crate::desktop::InkStyle`]; `None`: yours stay).
    pub ink: Option<crate::desktop::InkStyle>,
    /// Its desktop widgets drawn as comic panels: a solid plate, an ink
    /// outline and a hard shadow.
    pub inked_widgets: bool,
}

