/// The look with `id`.
pub fn find(id: &str) -> Option<&'static LookDef> {
    LOOKS.iter().find(|l| l.id == id)
}

/// The dock plugin's id (a look with a dock media chip switches it on).
const DOCK_ID: &str = crate::dock::DOCK_PLUGIN_ID;
/// The hairline's mini stats plugin (shipped off: a look switches it on).
pub const MINI_STATS_ID: &str = "mini-stats";
/// Bar items that ship switched off: a look that lays one out switches
/// its plugin on (and the next look off again).
pub const OPT_IN_ITEMS: &[&str] = &[MINI_STATS_ID, "net-speed", "processes", "drives", "pomodoro", "todo", "notes", "color-picker", crate::bar_styles::TASKBAR];

/// Paths of the settings a look may set on top ([`SettingUndo`]).
const EXTRA_PATHS: &[&str] = &["dock", "motion", "launcher.look", "notifications.position", "bar.auto_hide.mode", "hot_corners", "style.ink"];

/// The toml leaves under `t` (arrays count as one leaf), as dotted paths.
pub(crate) fn leaves(t: &Table, prefix: &str, out: &mut Vec<(String, Value)>) {
    for (k, v) in t {
        let path = if prefix.is_empty() { k.clone() } else { format!("{prefix}.{k}") };
        match v {
            Value::Table(sub) => leaves(sub, &path, out),
            v => out.push((path, v.clone())),
        }
    }
}

/// `cfg` as a toml table, then back after `edit` changed it.
fn edit_table(cfg: &mut ShellConfig, edit: impl FnOnce(&mut Table)) {
    let Ok(mut t) = crate::profiles::to_table(cfg) else { return };
    edit(&mut t);
    match Value::Table(t).try_into::<ShellConfig>() {
        Ok(next) => *cfg = next,
        Err(err) => tracing::warn!("looks: a setting didn't fit the config: {err}"),
    }
}

/// Puts back what a previous look set on top, where it still holds.
fn revert_settings(cfg: &mut ShellConfig, undo: &[SettingUndo]) {
    if undo.is_empty() {
        return;
    }
    edit_table(cfg, |t| {
        for u in undo {
            if crate::profiles::get_path(t, &u.path) == Some(&u.set) {
                crate::profiles::set_path(t, &u.path, u.was.clone());
            }
        }
    });
}

impl LookBar {
    pub fn layout(self) -> BarLayout {
        match self {
            LookBar::Plain { layout, .. } => layout,
            LookBar::Style(s) => s.layout(),
        }
    }

    pub fn position(self) -> BarPosition {
        match self {
            LookBar::Plain { position, .. } => position,
            LookBar::Style(s) => s.position(),
        }
    }

    pub fn style(self) -> Option<BarStyle> {
        match self {
            LookBar::Style(s) => Some(s),
            LookBar::Plain { .. } => None,
        }
    }
}

impl LookDef {
    pub fn seed_color(&self) -> Color {
        Color::oklch(self.seed.0, self.seed.1, self.seed.2)
    }

    pub fn layout(&self) -> BarLayout {
        self.bar.layout()
    }

    pub fn position(&self) -> BarPosition {
        self.bar.position()
    }

    /// The bar sits inside a frame round the screen.
    pub fn screen_frame(&self) -> bool {
        match self.bar {
            LookBar::Plain { screen_frame, .. } => screen_frame,
            LookBar::Style(s) => matches!(s, BarStyle::Expressive | BarStyle::Rail),
        }
    }

    /// The palette source this look uses with `opts` on `cfg`.
    pub fn theme_source(&self, cfg: &ShellConfig, opts: LookOptions) -> ThemeSource {
        match (&cfg.wallpaper.path, opts.wallpaper_colors) {
            (Some(path), true) => ThemeSource::Wallpaper { path: path.clone(), variant: self.variant, seed: 0 },
            _ => ThemeSource::Seed { color: self.seed_color(), variant: self.variant },
        }
    }

    /// `cfg` with this look applied (the wallpaper image is never changed;
    /// your widgets and bar items stay).
    pub fn apply(&self, cfg: &ShellConfig, opts: LookOptions) -> ShellConfig {
        self.apply_layered(cfg, opts, None, self.id)
    }

    /// Writes the settings the look names on top (dock, motion, launcher,
    /// notification corner, auto-hide, hot corners) and returns what each
    /// was before.
    fn set_extras(&self, c: &mut ShellConfig) -> Vec<SettingUndo> {
        let before = crate::profiles::to_table(c).unwrap_or_default();
        if let LookDock::On { magnification } = self.dock {
            c.dock.magnification = magnification;
            c.dock.position = crate::workflow::DockPosition::Bottom;
            c.dock.alignment = crate::dock::DockAlignment::Center;
        }
        if let Some(m) = self.motion {
            m.apply(&mut c.motion);
        }
        if let Some(l) = self.launcher.and_then(crate::workflow::LauncherLookPreset::find) {
            l.apply(&mut c.launcher.look);
        }
        if let Some(t) = self.toasts {
            c.notifications.position = t;
        }
        if let Some(mode) = self.auto_hide {
            c.bar.auto_hide.mode = mode;
        }
        if let Some(ink) = self.ink {
            c.style.ink = ink;
        }
        if let Some([tl, tr, bl, br]) = self.corners {
            let h = &mut c.hot_corners;
            h.enabled = true;
            for (corner, action) in [(&mut h.top_left, tl), (&mut h.top_right, tr), (&mut h.bottom_left, bl), (&mut h.bottom_right, br)] {
                corner.action = action;
            }
        }
        let after = crate::profiles::to_table(c).unwrap_or_default();
        let mut undo = Vec::new();
        for path in EXTRA_PATHS {
            let mut now = Vec::new();
            match crate::profiles::get_path(&after, path) {
                Some(Value::Table(t)) => leaves(t, path, &mut now),
                Some(v) => now.push((path.to_string(), v.clone())),
                None => {}
            }
            for (p, set) in now {
                let was = crate::profiles::get_path(&before, &p).cloned();
                if was.as_ref() != Some(&set) {
                    undo.push(SettingUndo { path: p, was, set });
                }
            }
        }
        undo
    }

    /// [`Self::apply`] with `layer` (one of your looks, a child of this
    /// one) on top, recorded as look `active`.
    pub fn apply_layered(&self, cfg: &ShellConfig, opts: LookOptions, layer: Option<&crate::user_looks::Delta>, active: &str) -> ShellConfig {
        let mut c = cfg.clone();
        // Your items, before anything moves.
        let (mine, shown_before) = (bar_items::yours(&c), bar_items::showing(&c));
        // A bar style preset gives way to the look's own bar.
        crate::bar_styles::clear(&mut c);
        let prev = std::mem::take(&mut c.looks);
        revert_settings(&mut c, &prev.settings);
        c.theme.source = self.theme_source(cfg, opts);
        c.theme.mode = if self.dark { ThemeMode::Dark } else { ThemeMode::Light };
        c.theme.adjustments = Default::default();
        match self.bar {
            LookBar::Plain { layout, position, screen_frame, opacity, capsules, height } => {
                let bar = &mut c.bar;
                bar.layout = layout;
                bar.position = position;
                bar.screen_frame = screen_frame;
                bar.opacity = opacity;
                bar.capsules = capsules;
                if let Some(h) = height {
                    bar.height = h;
                }
            }
            LookBar::Style(style) => style.apply_look(&mut c),
        }
        c.typography.ui_font = self.ui_font.into();
        c.typography.display_font = self.display_font.into();
        c.style.radius_scale = self.radius_scale;
        // The look's component designs, unless you keep your own. A design
        // you pick afterwards stays until you pick a look or preset again.
        if !cfg.looks.keep_components {
            self.components.apply(&mut c.style);
        }
        c.dock.media_chip = self.dock_media_chip;
        let settings = self.set_extras(&mut c);
        // The look's items (its zones, a style's rail), with your own
        // changes to them on top.
        let own = |z: &[&str]| z.iter().map(|s| s.to_string()).collect::<Vec<_>>();
        [c.bar.left, c.bar.center, c.bar.right] = self.zones.map(own);
        if let Some(rail) = self.bar.style().and_then(BarStyle::rail) {
            let left = &mut c.side_bars.left;
            [left.top, left.middle, left.bottom] = rail.map(own);
        }
        if let Some(layer) = layer {
            layer.merge_into(&mut c);
        }
        let rail = c.bar.style.and_then(BarStyle::rail).is_some().then(|| {
            let l = &c.side_bars.left;
            [l.top.clone(), l.middle.clone(), l.bottom.clone()]
        });
        let layout = Layout { bar: [c.bar.left.clone(), c.bar.center.clone(), c.bar.right.clone()], rail };
        let placed = bar_items::lay_out(&mut c, &layout, shown_before, &mine);
        if let Some(style) = c.bar.style {
            style.switch_on_signature(&mut c, &placed);
        }
        let target = layer.and_then(|l| l.widgets.clone()).unwrap_or_else(|| self.widgets());
        let widgets = merge_widgets(&mut c, &prev, target);
        c.desktop.widgets.migrated = true;
        crate::desktop_widgets::sync_depth_clock(&mut c);
        let wants = self.wants(&placed, &c);
        // What the previous look switched on and this one doesn't need goes
        // back off; what both need stays on (and stays the looks' doing).
        undo_plugins(&mut c, &prev, &wants);
        let mut state = LooksState {
            active: active.to_string(),
            wallpaper_colors: matches!(c.theme.source, ThemeSource::Wallpaper { .. }),
            keep_components: prev.keep_components,
            widgets,
            widgets_tracked: true,
            settings,
            ..LooksState::default()
        };
        for id in &wants {
            let was_disabled = c.plugins.disabled.iter().any(|d| d == id);
            c.plugins.disabled.retain(|d| d != id);
            if was_disabled || prev.plugins_undisabled.iter().any(|p| p == id) {
                state.plugins_undisabled.push(id.to_string());
            }
            let listed = c.plugins.enabled.iter().any(|e| e == id);
            if !listed {
                c.plugins.enabled.push(id.to_string());
            }
            if !listed || prev.plugins_enabled.iter().any(|p| p == id) {
                state.plugins_enabled.push(id.to_string());
            }
        }
        if self.dock == LookDock::Off && !wants.contains(&DOCK_ID.to_string()) && !c.plugins.disabled.iter().any(|d| d == DOCK_ID) && c.plugins.enabled.iter().any(|e| e == DOCK_ID) {
            c.plugins.disabled.push(DOCK_ID.to_string());
            state.plugins_disabled.push(DOCK_ID.to_string());
        }
        c.looks = state;
        c.looks.print = crate::user_looks::owned_print(&c);
        c
    }

    /// The plugins this look needs on (its own items; see also
    /// [`Self::wants`]).
    pub fn plugins(&self) -> Vec<&'static str> {
        let mut wants: Vec<&'static str> = Vec::new();
        if self.dock_media_chip || matches!(self.dock, LookDock::On { .. }) {
            wants.push(DOCK_ID);
        }
        for id in OPT_IN_ITEMS {
            if self.zones.iter().any(|z| z.contains(id)) && !wants.contains(id) {
                wants.push(id);
            }
        }
        wants
    }

    /// The plugins to switch on for the layout that was placed: the dock
    /// when the look shows it, and every shipped-off item it laid out.
    fn wants(&self, placed: &[String], c: &ShellConfig) -> Vec<String> {
        let mut wants: Vec<String> = Vec::new();
        if c.dock.media_chip || matches!(self.dock, LookDock::On { .. }) {
            wants.push(DOCK_ID.to_string());
        }
        for id in OPT_IN_ITEMS {
            let style_did = c.bar.style_items.enabled.iter().chain(&c.bar.style_items.undisabled).any(|s| s == id);
            if placed.iter().any(|p| p == id) && !style_did && !wants.iter().any(|w| w == id) {
                wants.push(id.to_string());
            }
        }
        wants
    }
}

/// Reverts the plugin switches recorded in `looks` except for `keep`: ids
/// a look added to `plugins.enabled` leave it again, ids it took out of
/// `plugins.disabled` go back in, ids it switched off come back on. A
/// switch you changed since (the plugin no longer listed, or disabled
/// again) is left as you set it.
fn undo_plugins(c: &mut ShellConfig, looks: &LooksState, keep: &[String]) {
    let kept = |id: &String| keep.iter().any(|k| k == id);
    for id in looks.plugins_enabled.iter().filter(|id| !kept(id)) {
        if !crate::bar_styles::placed_by_you(c, id) {
            c.plugins.enabled.retain(|e| e != id);
        }
    }
    for id in looks.plugins_undisabled.iter().filter(|id| !kept(id)) {
        if !crate::bar_styles::placed_by_you(c, id) && !c.plugins.disabled.iter().any(|d| d == id) && !c.plugins.enabled.iter().any(|e| e == id) {
            c.plugins.disabled.push(id.clone());
        }
    }
    for id in &looks.plugins_disabled {
        c.plugins.disabled.retain(|d| d != id);
    }
}

/// A widget's fingerprint: FNV-1a over its TOML text without its id
/// (stable across builds, unlike `std`'s hasher).
pub fn widget_print(w: &DesktopWidget) -> String {
    let mut w = w.clone();
    w.id.clear();
    format!("{:016x}", crate::user_looks::fnv1a(toml::to_string(&w).unwrap_or_default().as_bytes()))
}

/// Takes away the previous look's widgets you didn't change, adds
/// `target` (fresh ids, painted under yours) and returns the new record.
/// Your widgets are never touched; when the list is full the look's
/// widgets that don't fit are left out, never yours.
fn merge_widgets(c: &mut ShellConfig, prev: &LooksState, target: Vec<DesktopWidget>) -> Vec<OwnedWidget> {
    let legacy = (!prev.widgets_tracked).then(|| find(&prev.active)).flatten().map(|l| l.widgets());
    let list = &mut c.desktop.widgets;
    list.items.retain(|w| {
        let recorded = prev.widgets.iter().any(|o| o.id == w.id && o.print == widget_print(w));
        // An older config: the look replaced the list, so a widget equal to
        // one of the active look's own (bar its id) is the look's.
        let legacy_own = legacy.as_ref().is_some_and(|own| own.iter().any(|o| widget_print(o) == widget_print(w)));
        !(recorded || legacy_own)
    });
    let mut owned = Vec::new();
    for (at, mut w) in target.into_iter().enumerate() {
        if list.items.len() >= crate::desktop_widgets::ranges::MAX_WIDGETS {
            break;
        }
        w.id = list.next_id(w.kind.id());
        owned.push(OwnedWidget { id: w.id.clone(), print: widget_print(&w) });
        list.items.insert(at, w);
    }
    owned
}

impl LookDef {
    /// The look's desktop widgets, in paint order.
    pub fn widgets(&self) -> Vec<DesktopWidget> {
        let mut list = crate::desktop_widgets::DesktopWidgetsConfig::default();
        let place = |anchor: Anchor, x: f32, y: f32| Placement { anchor, x, y, ..Placement::default() };
        if let Some((face, anchor)) = self.clock {
            let (fx, fy) = anchor.fraction();
            let inward = |f: f32, d: f32| if f < 0.25 { d } else if f > 0.75 { -d } else { 0.0 };
            let mut p = place(anchor, inward(fx, LOOK_MARGIN.0), inward(fy, LOOK_MARGIN.1));
            p.depth = if self.depth { Depth::Behind } else { Depth::Front };
            if self.depth {
                p.scale = DEPTH_CLOCK_SCALE;
            }
            let mut clock = ClockWidget { face, ..ClockWidget::default() };
            if self.inked_widgets {
                ink_look(&mut clock.look);
            }
            list.add(DesktopWidget { place: p, kind: WidgetKind::Clock(clock), ..DesktopWidget::default() });
        }
        if let Some(anchor) = self.monitor {
            let mut p = place(anchor, LOOK_MARGIN.0, 0.0);
            p.depth = Depth::Front;
            let mut monitor = MonitorWidget::default();
            if self.inked_widgets {
                ink_look(&mut monitor.look);
            }
            list.add(DesktopWidget { place: p, kind: WidgetKind::Monitor(monitor), ..DesktopWidget::default() });
        }
        if let Some(text) = self.decoration {
            let mut p = place(Anchor::Right, -LOOK_MARGIN.0, 0.0);
            p.depth = Depth::Behind;
            p.opacity = DECORATION_OPACITY;
            // Vertical text: katakana stands one character under another;
            // Arabic keeps its joined letters, its line turned with the
            // baseline toward the screen's middle.
            let d = Decoration { shape: DecorShape::Text, text: text.into(), vertical: true, size: DECORATION_SIZE_PX, ..Decoration::default() };
            list.add(DesktopWidget { place: p, kind: WidgetKind::Decoration(d), ..DesktopWidget::default() });
        }
        let mut add = |card: &str, anchor: Anchor| {
            list.add(cards::new_card(card, anchor));
        };
        if let Some(a) = self.now_playing {
            add(NOW_PLAYING, a);
        }
        if let Some(a) = self.calendar {
            add(CALENDAR, a);
        }
        match self.visualizer {
            LookVisualizer::None => {}
            LookVisualizer::Wave => add(WAVE, Anchor::Bottom),
            LookVisualizer::Framed => add(FRAMED_BARS, Anchor::BottomLeft),
            LookVisualizer::Mirrored => add(MIRRORED_BARS, Anchor::Bottom),
        }
        list.items
    }
}

/// A comic panel: a solid plate in an ink outline on a hard ink shadow
/// (text stays on the plate's own surface colour, so its contrast holds).
fn ink_look(look: &mut crate::desktop_widgets::Look) {
    use crate::desktop_widgets::{Plate, Tone};
    look.plate = Plate::Solid;
    look.plate_opacity = 1.0;
    look.outline_width = INK_WIDGET_OUTLINE_PX;
    // The outline in the text's own colour: dark ink on a light plate,
    // light ink on a dark one, so the edge stays strong in both.
    look.outline_tone = Tone::OnSurface;
    look.shadow = crate::desktop_widgets::ShadowKind::Hard;
    (look.shadow_x, look.shadow_y) = (INK_WIDGET_SHADOW_PX, INK_WIDGET_SHADOW_PX);
    look.shadow_blur = 0.0;
    look.shadow_opacity = 1.0;
    look.shadow_tone = Tone::Custom;
    look.shadow_color = INK_WIDGET_COLOR.into();
}

/// An inked widget's outline and shadow (reference px) and ink.
const INK_WIDGET_OUTLINE_PX: f32 = 4.0;
const INK_WIDGET_SHADOW_PX: f32 = 7.0;
const INK_WIDGET_COLOR: &str = "#16131a";

/// Inset of a look's corner / edge widgets (fractions of the display).
const LOOK_MARGIN: (f32, f32) = (0.04, 0.07);
/// A clock behind the subject is drawn large.
const DEPTH_CLOCK_SCALE: f32 = 1.8;
/// Vertical decoration text: size (reference px) and opacity.
const DECORATION_SIZE_PX: f32 = 64.0;
const DECORATION_OPACITY: f32 = 0.55;

/// Snapshot of `cfg` to restore later — `None` when a look is already
/// active (the snapshot of your own setup is kept, not replaced by a look).
pub fn before_snapshot(cfg: &ShellConfig, saved: &str) -> Option<crate::profiles::Profile> {
    if !cfg.looks.active.is_empty() {
        return None;
    }
    crate::profiles::snapshot_paths(cfg, BEFORE_PROFILE, "Your setup before the first look", SNAPSHOT_PATHS, saved).ok()
}

/// `cfg` restored from `before` (and no look active). The snapshot brings
/// the plugin lists back exactly; plugins you switched on yourself while a
/// look was applied stay on, and so do your widgets and bar items. The
/// settings the look set on top go back to what they were.
pub fn restore(cfg: &ShellConfig, before: &crate::profiles::Profile) -> anyhow::Result<ShellConfig> {
    let (mine, shown_before) = (bar_items::yours(cfg), bar_items::showing(cfg));
    let mut look_off = cfg.clone();
    revert_settings(&mut look_off, &cfg.looks.settings);
    let mut c = crate::profiles::apply(&look_off, before)?;
    for id in &cfg.plugins.enabled {
        let looks_did = cfg.looks.plugins_enabled.contains(id);
        if !looks_did && !c.plugins.enabled.contains(id) {
            c.plugins.disabled.retain(|d| d != id);
            c.plugins.enabled.push(id.clone());
        }
    }
    // Your widgets: those you have now (the look's own you left as it put
    // them go); an older look that replaced the list leaves yours in the
    // snapshot, so those come back too.
    let mut yours_now = cfg.desktop.widgets.items.clone();
    let mut probe = LooksState::default();
    merge_widgets_into(&mut yours_now, &cfg.looks, &mut probe);
    if !cfg.looks.widgets_tracked {
        for w in &c.desktop.widgets.items {
            if !yours_now.iter().any(|y| y.id == w.id) {
                yours_now.push(w.clone());
            }
        }
    }
    c.desktop.widgets.items = yours_now;
    crate::desktop_widgets::sync_depth_clock(&mut c);
    bar_items::bring_back(&mut c, &mine, shown_before);
    // Keeping your component designs is your choice, not the look's.
    c.looks = LooksState { keep_components: cfg.looks.keep_components, ..LooksState::default() };
    Ok(c)
}

/// The widgets of `items` that are yours: the look's own you left as it
/// put them (and, for an older config, those equal to its own) go.
fn merge_widgets_into(items: &mut Vec<DesktopWidget>, looks: &LooksState, _scratch: &mut LooksState) {
    let legacy = (!looks.widgets_tracked).then(|| find(&looks.active)).flatten().map(|l| l.widgets());
    items.retain(|w| {
        let recorded = looks.widgets.iter().any(|o| o.id == w.id && o.print == widget_print(w));
        let legacy_own = legacy.as_ref().is_some_and(|own| own.iter().any(|o| widget_print(o) == widget_print(w)));
        !(recorded || legacy_own)
    });
}

/// The widgets of `cfg` that are yours (not a look's untouched own).
pub fn your_widgets(cfg: &ShellConfig) -> Vec<DesktopWidget> {
    let mut items = cfg.desktop.widgets.items.clone();
    merge_widgets_into(&mut items, &cfg.looks, &mut LooksState::default());
    items
}

/// The widgets of `cfg` the active look placed (and you left as they are).
pub fn look_widgets(cfg: &ShellConfig) -> Vec<DesktopWidget> {
    cfg.desktop.widgets.items.iter().filter(|w| cfg.looks.widgets.iter().any(|o| o.id == w.id)).cloned().collect()
}

#[cfg(test)]
mod tests;
